// Byte-exact reimplementation of the Python argparse CLI of test19.py:
//   ArgumentParser(description="Markdown processing with transformation chain")
//   with required options --a .. --f (one string value each) plus -h/--help.
//
// Behavior was probed against /workspace/dataset/test19_executable:
//   - "--x value" and "--x=value" forms; "=" takes everything after the first "="
//   - unambiguous long-option prefix matching ("--h", "--he", ... -> "--help")
//   - help to stdout, exit 0 (fires even with missing required args, and even
//     when unknown args precede it)
//   - errors: usage line + "PROG: error: MSG" on stderr, exit 2, stdout empty
//   - missing-required checked before unrecognized extras
//   - negative-number tokens (^-\d+$ | ^-\d*\.\d+$) and a lone "-" are values
//   - duplicate options: last wins
//   - bare "--" is not swallowed: it and everything after it become extras
//   - "-h<x>" fires help; "-h=<x>" -> "ignored explicit argument '<x>'"

import { writeSync } from 'node:fs';

const VALUE_OPTIONS = ['--a', '--b', '--c', '--d', '--e', '--f'];
const LONG_OPTIONS = ['--help', ...VALUE_OPTIONS];
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B --c C --d D --e E --f F\n`;
}

function helpText(prog) {
  return usageLine(prog) +
    '\n' +
    'Markdown processing with transformation chain\n' +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n' +
    '  --b B\n' +
    '  --c C\n' +
    '  --d D\n' +
    '  --e E\n' +
    '  --f F\n';
}

function errorExit(prog, message) {
  writeSync(2, usageLine(prog));
  writeSync(2, `${prog}: error: ${message}\n`);
  process.exit(2);
}

function helpExit(prog) {
  writeSync(1, helpText(prog));
  process.exit(0);
}

// A token is "option-like" (parsed as an option string, never consumed as an
// option value) when it starts with '-', is not a lone '-', and does not match
// argparse's negative-number pattern (this parser has no options that look
// like negative numbers).
function isOptionLike(token) {
  return token.length > 1 && token[0] === '-' && !NEGATIVE_NUMBER.test(token);
}

export function parseArgs(argv, prog) {
  const values = {};
  const seen = new Set();
  const extras = [];
  let afterSeparator = false;

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    // Once a bare "--" is seen, it and every remaining token are extras
    // (no positionals are defined, so nothing consumes them).
    if (afterSeparator) {
      extras.push(token);
      i += 1;
      continue;
    }
    if (token === '--') {
      extras.push(token);
      afterSeparator = true;
      i += 1;
      continue;
    }

    if (!isOptionLike(token)) {
      // Plain token / lone "-" / negative number: no positionals defined.
      extras.push(token);
      i += 1;
      continue;
    }

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);
      const explicitValue = eq === -1 ? null : token.slice(eq + 1);

      let option = LONG_OPTIONS.includes(name) ? name : null;
      if (option === null) {
        const matches = LONG_OPTIONS.filter(o => o.startsWith(name));
        if (matches.length === 1) {
          option = matches[0];
        } else if (matches.length > 1) {
          errorExit(prog, `ambiguous option: ${token} could match ${matches.join(', ')}`);
        }
      }
      if (option === null) {
        // Unknown long option: whole token (incl. any "=value") is an extra.
        extras.push(token);
        i += 1;
        continue;
      }
      if (option === '--help') {
        if (explicitValue !== null) {
          errorExit(prog, `argument -h/--help: ignored explicit argument '${explicitValue}'`);
        }
        helpExit(prog);
      }
      // Value option.
      let value;
      if (explicitValue !== null) {
        value = explicitValue;
        i += 1;
      } else {
        const next = argv[i + 1];
        if (next === undefined || isOptionLike(next)) {
          errorExit(prog, `argument ${option}: expected one argument`);
        }
        value = next;
        i += 2;
      }
      values[option.slice(2)] = value; // duplicate: last wins
      seen.add(option);
      continue;
    }

    // Single-dash token.
    if (token[1] === 'h') {
      if (token.length === 2) {
        helpExit(prog); // -h
      }
      if (token[2] === '=') {
        // -h=<x>: argparse splits on '=' and rejects the explicit argument.
        errorExit(prog, `argument -h/--help: ignored explicit argument '${token.slice(3)}'`);
      }
      // -h<x>: '-h' is consumed first, so the help action fires and exits.
      helpExit(prog);
    }
    // Unknown short option: whole token is an extra.
    extras.push(token);
    i += 1;
  }

  const missing = VALUE_OPTIONS.filter(o => !seen.has(o));
  if (missing.length > 0) {
    errorExit(prog, `the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    errorExit(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return {
    a: values.a,
    b: values.b,
    c: values.c,
    d: values.d,
    e: values.e,
    f: values.f,
  };
}

