import { basename } from 'node:path';
import { parseArgs } from './lib/argparse.mjs';
import { markdown } from './lib/markdown.mjs';
import { highlightCode } from './lib/highlight/index.mjs';

function main() {
  const prog = basename(process.argv[1] || 'test19.mjs');
  const args = parseArgs(process.argv.slice(2), prog);

  // Phase 1: Basic conversions
  const phase1_a = markdown(args.a);
  const phase1_b = markdown(args.b);
  const phase1_c = markdown(args.c);

  // Phase 2: With extensions
  const phase2_d = markdown(args.d, { extensions: ['extra', 'tables'] });
  const phase2_e = markdown(args.e, {
    extensions: ['codehilite', 'fenced_code'],
    highlight: highlightCode,
  });
  const phase2_f = markdown(args.f, { extensions: ['toc'] });

  // Phase 3: Combined processing (exact f-string template from test19.py,
  // including its leading and trailing newlines)
  const phase3_combined = markdown(`
